const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  const getInfo = (obj) => new Promise((resolve, reject) => obj.getInfo((v, e) => e ? reject(e) : resolve(v)));
  const fmt = (x) => (x === null || x === undefined || !isFinite(x) ? String(x) : x.toFixed(2));
  const scale = 5500;

  try {
    // 1) Geometry
    const somalia = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Somalia'))
      .geometry();

    // 2) Collections and basic checks
    let datasetUsed = 'UCSB-CHG/CHIRPS/Monthly';
    let col = ee.ImageCollection(datasetUsed).select('precipitation');

    let climCol = col
      .filter(ee.Filter.calendarRange(1981, 2021, 'year'))
      .filter(ee.Filter.calendarRange(3, 9, 'month'));
    let y2022Col = col
      .filter(ee.Filter.calendarRange(2022, 2022, 'year'))
      .filter(ee.Filter.calendarRange(3, 9, 'month'));

    let climCountImgs = await getInfo(climCol.size());
    let y2022CountImgs = await getInfo(y2022Col.size());

    // Fallback to DAILY if empty
    if (climCountImgs === 0 || y2022CountImgs === 0) {
      datasetUsed = 'UCSB-CHG/CHIRPS/DAILY';
      col = ee.ImageCollection(datasetUsed).select('precipitation');
      climCol = col
        .filter(ee.Filter.calendarRange(1981, 2021, 'year'))
        .filter(ee.Filter.calendarRange(3, 9, 'month'));
      y2022Col = col
        .filter(ee.Filter.calendarRange(2022, 2022, 'year'))
        .filter(ee.Filter.calendarRange(3, 9, 'month'));
      climCountImgs = await getInfo(climCol.size());
      y2022CountImgs = await getInfo(y2022Col.size());
      if (climCountImgs === 0 || y2022CountImgs === 0) {
        console.log(`Dataset: ${datasetUsed}`);
        console.log(`1981-2021 Mar-Sep images: ${climCountImgs}`);
        console.log(`2022 Mar-Sep images: ${y2022CountImgs}`);
        console.log('C1');
        return;
      }
    }

    // 3) Compute seasonal totals
    // Climatology seasonal mean total per pixel = (sum of all Mar-Sep images over 1981-2021) / 41
    const yearsN = 41;
    const climTotalMeanImg = climCol.sum().divide(yearsN);
    const y2022TotalImg = y2022Col.sum();

    // 4) Pixel counts for validity
    const y2022PixCount = await getInfo(y2022TotalImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: somalia,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation'));
    const climPixCount = await getInfo(climTotalMeanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: somalia,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation'));

    if (!y2022PixCount || !climPixCount || y2022PixCount === 0 || climPixCount === 0) {
      console.log(`Dataset: ${datasetUsed}`);
      console.log(`1981-2021 Mar-Sep images: ${climCountImgs}`);
      console.log(`2022 Mar-Sep images: ${y2022CountImgs}`);
      console.log(`Pixels (2022 total): ${y2022PixCount || 0}`);
      console.log(`Pixels (Climatology mean): ${climPixCount || 0}`);
      console.log('C2');
      return;
    }

    // 5) Area-mean rainfall (mm)
    const y2022Mean = await getInfo(y2022TotalImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: somalia,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation'));
    const climMean = await getInfo(climTotalMeanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: somalia,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation'));

    // 6) Validate results
    const invalid = (v) => (v === null || v === undefined || !isFinite(v) || v < 0 || v > 10000);
    if (invalid(y2022Mean) || invalid(climMean)) {
      console.log(`Dataset: ${datasetUsed}`);
      console.log(`1981-2021 Mar-Sep images: ${climCountImgs}`);
      console.log(`2022 Mar-Sep images: ${y2022CountImgs}`);
      console.log(`Pixels (2022 total): ${y2022PixCount}`);
      console.log(`Pixels (Climatology mean): ${climPixCount}`);
      console.log(`2022 area-mean total (mm): ${fmt(y2022Mean)}`);
      console.log(`1981-2021 mean area-mean total (mm): ${fmt(climMean)}`);
      console.log('C3');
      return;
    }

    // 7) Output concise evidence and final answer
    const diff = y2022Mean - climMean;
    console.log(`Dataset: ${datasetUsed}`);
    console.log(`1981-2021 Mar-Sep images: ${climCountImgs}`);
    console.log(`2022 Mar-Sep images: ${y2022CountImgs}`);
    console.log(`Pixels (2022 total): ${y2022PixCount}`);
    console.log(`Pixels (Climatology mean): ${climPixCount}`);
    console.log(`2022 area-mean total (mm): ${fmt(y2022Mean)}`);
    console.log(`1981-2021 mean area-mean total (mm): ${fmt(climMean)}`);
    console.log(`Difference (2022 - climatology) mm: ${fmt(diff)}`);
    console.log(y2022Mean < climMean ? 'A' : 'B');
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
